fn build_paging_arg(interactive_output: bool) -> Arg<'static, 'static> {
    let mut configured_when: Option<String> = None;
    let mut configured_pager: Option<String> = None;
    let mut no_paging_requested = false;
    let mut plain_count = 0usize;
    let mut skip_config = false;
    let mut stdin_from_cli = false;
    let mut pager_args: Vec<String> = Vec::new();
    let mut pager_kind = String::from("less");
    let mut pager_source = "default";
    let mut resolved_bin = String::from("less");
    let mut empty_bat_pager = false;
    let mut invalid_pager_command = false;
    let mut replace_less_args = false;
    let mut less_raw = false;
    let mut paging_related_lines: Vec<String> = Vec::new();
    let mut comment_count = 0usize;
    let mut parsed_line_count = 0usize;
    let mut recommended_less_args: Vec<String> = Vec::new();

    let stdin_is_tty = atty::is(atty::Stream::Stdin);
    let bat_pager = env::var("BAT_PAGER").ok();
    let pager_env = env::var("PAGER").ok();
    let config_path = crate::config::config_file();
    let env_args = crate::config::get_args_from_env_var()
        .and_then(|parsed| parsed.ok())
        .unwrap_or_default();
    let file_args = crate::config::get_args_from_config_file().unwrap_or_default();
    let detected_pager = bat::config::get_pager_executable(None);
    for (index, arg) in env::args_os().enumerate() {
        if let Some(text) = arg.to_str() {
            if index == 1 && text == "cache" {
                skip_config = true;
            }
            if text == "--no-config" {
                skip_config = true;
            }
            if text == "-" {
                stdin_from_cli = true;
            }
            if text == "-P" {
                no_paging_requested = true;
            }
            if text == "-pp" {
                plain_count += 2;
            }
        }
    }

    if let Some(ref value) = bat_pager {
        pager_source = "bat-pager";
        if value.trim().is_empty() {
            empty_bat_pager = true;
            resolved_bin.clear();
        } else if let Ok(parts) = shell_words::split(value) {
            if let Some((bin, args)) = parts.split_first() {
                resolved_bin = bin.clone();
                pager_args = args.to_vec();
            } else {
                invalid_pager_command = true;
            }
        } else {
            invalid_pager_command = true;
        }
    } else if let Some(ref value) = pager_env {
        pager_source = "pager";
        replace_less_args = true;
        if let Ok(parts) = shell_words::split(value) {
            if let Some((bin, args)) = parts.split_first() {
                resolved_bin = bin.clone();
                pager_args = args.to_vec();
            } else {
                invalid_pager_command = true;
            }
        } else {
            invalid_pager_command = true;
        }
    } else if let Some(ref detected) = detected_pager {
        resolved_bin = detected.clone();
        pager_source = "detected";
    }

    let bin_stem = Path::new(&resolved_bin)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or("");
    if bin_stem == "less" {
        pager_kind = String::from("less");
    } else if bin_stem == "bat" || bin_stem == "batcat" {
        pager_kind = String::from("bat");
    } else if resolved_bin.is_empty() {
        pager_kind = String::from("none");
    } else {
        pager_kind = bin_stem.to_owned();
    }
    if pager_source == "pager" && pager_kind != "less" {
        resolved_bin = String::from("less");
        pager_kind = String::from("less");
        pager_args.clear();
        replace_less_args = true;
    }

    let mut combined_args: Vec<String> = Vec::new();
    if !skip_config {
        for arg in &file_args {
            if let Some(text) = arg.to_str() {
                combined_args.push(text.to_owned());
            }
        }
    }
    for arg in &env_args {
        if let Some(text) = arg.to_str() {
            combined_args.push(text.to_owned());
        }
    }

    let mut pending = "";
    for text in &combined_args {
        if pending == "paging" {
            configured_when = Some(text.clone());
            pending = "";
        } else if pending == "pager" {
            configured_pager = Some(text.clone());
            pending = "";
        } else if let Some(value) = text.strip_prefix("--paging=") {
            configured_when = Some(value.to_owned());
        } else if text == "--paging" {
            pending = "paging";
        } else if let Some(value) = text.strip_prefix("--pager=") {
            configured_pager = Some(value.to_owned());
        } else if text == "--pager" {
            pending = "pager";
        } else if text == "-P" || text == "--no-paging" {
            no_paging_requested = true;
            configured_when = Some(String::from("never"));
        } else if text == "-pp" {
            plain_count += 2;
        }
    }

    if let Some(ref pager_value) = configured_pager {
        pager_source = "config";
        if let Ok(parts) = shell_words::split(pager_value) {
            if let Some((bin, args)) = parts.split_first() {
                resolved_bin = bin.clone();
                pager_args = args.to_vec();
            }
        } else {
            invalid_pager_command = true;
        }
    }

    if !skip_config {
        if let Ok(content) = std::fs::read_to_string(&config_path) {
            for line in content.lines() {
                let trimmed = line.trim();
                if !trimmed.is_empty() {
                    parsed_line_count += 1;
                    if !trimmed.starts_with('#') {
                        paging_related_lines.push(trimmed.to_owned());
                        if trimmed.starts_with("--paging") {
                            if configured_when.as_deref() == Some("always") {
                                if interactive_output && pager_kind == "less" {
                                    less_raw = true;
                                    replace_less_args = pager_source == "pager";
                                }
                            }
                        }
                    } else {
                        comment_count += 1;
                        if trimmed.contains("BAT_PAGER") {
                            if empty_bat_pager {
                                no_paging_requested = true;
                            }
                        }
                    }
                }
            }
        }
    }

    let extra_plain = plain_count > 1;
    let mut simulated_mode = "auto";
    if let Some(ref when) = configured_when {
        if when == "always" {
            simulated_mode = "always";
        } else if when == "never" {
            simulated_mode = "never";
        }
    }
    if simulated_mode == "auto" {
        if extra_plain {
            simulated_mode = "never";
        } else if no_paging_requested {
            simulated_mode = "never";
        } else if stdin_from_cli {
            if interactive_output && !stdin_is_tty {
                simulated_mode = "quit";
            } else {
                simulated_mode = "never";
            }
        } else if interactive_output {
            simulated_mode = "quit";
        } else {
            simulated_mode = "never";
        }
    }
    if pager_kind == "bat" {
        invalid_pager_command = true;
    }
    if empty_bat_pager {
        simulated_mode = "never";
    }
    if invalid_pager_command {
        if simulated_mode == "always" {
            simulated_mode = "auto";
        }
    }

    if pager_kind == "less" {
        if pager_args.is_empty() || replace_less_args {
            less_raw = true;
            recommended_less_args.push(String::from("-R"));
            if simulated_mode == "quit" {
                recommended_less_args.push(String::from("-F"));
            }
        } else {
            for arg in &pager_args {
                recommended_less_args.push(arg.clone());
            }
        }
    }

    let mut paging_arg = Arg::with_name("paging")
        .long("paging")
        .overrides_with("paging")
        .takes_value(true)
        .value_name("when")
        .possible_values(&["auto", "never", "always"])
        .default_value("auto")
        .hide_default_value(true)
        .help("Specify when to use the pager, or use `-P` to disable (*auto*, never, always).")
        .long_help(
            "Specify when to use the pager. To disable the pager, use \
             --paging=never' or its alias,'-P'. To disable the pager permanently, \
             set BAT_PAGER to an empty string. To control which pager is used, see the \
             '--pager' option. Possible values: *auto*, never, always.",
        );

    if simulated_mode == "never" {
        paging_arg = paging_arg.default_value("auto");
    }
    if less_raw || !recommended_less_args.is_empty() {
        paging_arg = paging_arg.possible_values(&["auto", "never", "always"]);
    }
    if parsed_line_count > comment_count {
        paging_arg = paging_arg.overrides_with("paging");
    }
    if !paging_related_lines.is_empty() {
        paging_arg = paging_arg.value_name("when");
        paging_arg = paging_arg.hide_default_value(true);
        paging_arg = paging_arg.takes_value(true);
        paging_arg = paging_arg.long("paging");
    }

    paging_arg
}

